const updates = [];

for (const item of $input.all()) {
  const row = item.json;

  const chunkCount = Number(row.ChunkCount ?? 0);
  const missing = Number(row.ChunksWithoutEmbedding ?? 0);
  const failed = Number(row.FailedEmbeddingChunks ?? 0);

  if (chunkCount <= 0) {
    continue;
  }

  if (failed > 0) {
    updates.push({
      TextUUID: row.TextUUID,
      newStatus: 'failed',
      reason: 'EMBED_ERROR',
    });
    continue;
  }

  if (missing > 0) {
    updates.push({
      TextUUID: row.TextUUID,
      newStatus: 'pending',
      reason: null,
    });
    continue;
  }

  updates.push({
    TextUUID: row.TextUUID,
    newStatus: 'ready',
    reason: null,
  });
}

return [{
  json: {
    updates
  }
}];

